"""
How long does the arm collision checker of the IK verification take to build, the first time and for another pedestal height? (a follow-up of experiments/stance_check_profile.py: its cold run
built one checker in 14.8 s, while a comment in experiments/stance_sensitivity.py says a rebuild takes 0.2 s). Timing only.

    MUJOCO_GL=egl python experiments/stance_checker_build_time.py

Builds src/arm_collision.ArmCollisionChecker for several pedestal heights in turn, as Ctx.checker does (it keeps only the two most recent), and prints the time of each.
"""

import sys
import time
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
sys.path.insert(0, str(PROJECT_ROOT / "experiments"))

import stance_from_map as SFM  # noqa: E402
import stance_sensitivity as SS  # noqa: E402
import stance_two_points as S2  # noqa: E402
from src.arm_collision import ArmCollisionChecker  # noqa: E402
from src.task_config import STAGING_CFG  # noqa: E402


def main():
    R = SS.Runner("open_b45", {**SFM.CASES["open_b45"], "cameras": True})
    ctx = R.ctx
    for q in (0.16, 0.16, 0.12, 0.20, 0.10, 0.16):
        t0 = time.perf_counter()
        ArmCollisionChecker(ctx.m, S2.SIDE, ctx.home_other, finger_open=STAGING_CFG["finger_open"], pedestal_q=float(q))
        print(f"ArmCollisionChecker for pedestal {q:.2f}: {time.perf_counter() - t0:.2f} s", flush=True)
    for q in (0.16, 0.12, 0.20):
        t0 = time.perf_counter()
        ctx.checker(q)
        print(f"ctx.checker({q:.2f}) (kept {len(ctx._checkers)}): {time.perf_counter() - t0:.2f} s", flush=True)


if __name__ == "__main__":
    main()
